    /**
     * Handles create a Advisor.  if not key provided, calls create, otherwise calls save
     * @param		Advisor	advisor
     * @return		Advisor 
     */
	@PostMapping("/create")
    public Advisor create( @RequestBody(required=true) CreateAdvisorCommand command ) {
    	Advisor entity = null;
		try {       
        	
			entity = AdvisorBusinessDelegate.getAdvisorInstance().createAdvisor( command );
        }
        catch( Throwable exc ) {
        	LOGGER.log( Level.WARNING, exc.getMessage(), exc );        	
        }
		
		return entity;
    }

    /**
     * Handles updating a Advisor.  if no key provided, calls create, otherwise calls save
     * @param		Advisor advisor
     * @return		Advisor
     */
	@PutMapping("/update")
    public Advisor update( @RequestBody(required=true) UpdateAdvisorCommand command ) {
		Advisor entity = null;
		try {                        	        
			// -----------------------------------------------
			// delegate the UpdateAdvisorCommand
			// -----------------------------------------------
			entity = AdvisorBusinessDelegate.getAdvisorInstance().updateAdvisor(command);;
	    }
	    catch( Throwable exc ) {
	    	LOGGER.log( Level.WARNING, "AdvisorController:update() - successfully update Advisor - " + exc.getMessage());        	
	    }		
		
		return entity;
	}
 
    /**
     * Handles deleting a Advisor entity
     * @param		command ${class.getDeleteCommandAlias()}
     */
    @DeleteMapping("/delete")    
    public void delete( @RequestBody(required=true) DeleteAdvisorCommand command ) {                
    	try {
        	AdvisorBusinessDelegate delegate = AdvisorBusinessDelegate.getAdvisorInstance();

        	delegate.delete( command );
    		LOGGER.log( Level.WARNING, "Successfully deleted Advisor with key " + command.getAdvisorId() );
        }
        catch( Throwable exc ) {
        	LOGGER.log( Level.WARNING, exc.getMessage() );
        }

	}        
	
    /**
     * Handles loading a Advisor using a UUID
     * @param		UUID uuid 
     * @return		Advisor
     */    
    @GetMapping("/load")
    public Advisor load( @RequestParam(required=true) UUID uuid ) {    	
    	Advisor entity = null;

    	try {  
    		entity = AdvisorBusinessDelegate.getAdvisorInstance().getAdvisor( new AdvisorFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Advisor using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Advisor business objects
     * @return		Set<Advisor>
     */
    @GetMapping("/")
    public List<Advisor> loadAll() {                
    	List<Advisor> advisorList = null;
        
    	try {
            // load the Advisor
            advisorList = AdvisorBusinessDelegate.getAdvisorInstance().getAllAdvisor();
            
            if ( advisorList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Advisors" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Advisors ", exc );
        	return null;
        }

        return advisorList;
                            
    }

